#include <iostream>
#include <vector>
#include <random>
#include <cmath>
#include <iomanip>

int main() {
    // 1. Set up the random number generator (Modern C++ approach)
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> distrib(1, 50);

    const int NUM_VALUES = 10;
    std::vector<int> radius_array;
    std::vector<double> areas_array;

    // Generate 10 random radius values
    for (int i = 0; i < NUM_VALUES; ++i) {
        radius_array.push_back(distrib(gen));
    }

    // 2. Calculate the area for each radius
    // std::acos(-1.0) is a standard way to get a highly precise value for Pi
    const double PI = std::acos(-1.0); 

    for (int r : radius_array) {
        areas_array.push_back(PI * std::pow(r, 2));
    }

    // 3. Display the results
    std::cout << "Radius | Area\n";
    std::cout << "--------------------\n";

    for (size_t i = 0; i < radius_array.size(); ++i) {
        std::cout << std::setw(6) << radius_array[i] << " | "
                  << std::fixed << std::setprecision(2) << areas_array[i] << "\n";
    }

    return 0;
}
